/**
 * Type stub for the CJS FoxSchema bundle generated by scripts/bundle-foxschema.mjs.
 * The .cjs file itself is produced at build time and is not linted by the n8n scanner.
 */
export type FoxRoutineParameter = {
	name: string;
	type: string;
	mode: string;
	ordinal?: number;
};

export type FoxColumnInfo = {
	name: string;
	type: string;
	nullable?: boolean;
	defaultValue?: string;
	primaryKey?: boolean;
	identity?: boolean;
};

export type FoxTableSchema = {
	name: string;
	objectType: string;
	columns: FoxColumnInfo[];
	parameters?: FoxRoutineParameter[];
	functionKind?: string;
	definition?: string;
};

export interface OpenDatabase {
	readonly dialect: string;
	query<T = Record<string, unknown>>(sql: string, params?: readonly unknown[]): Promise<T[]>;
	close(): Promise<void>;
}

export function openDatabase(
	dialect: string,
	options: Record<string, unknown>,
	opts?: { pooled?: boolean },
): Promise<OpenDatabase>;

export function queryOnce<T = Record<string, unknown>>(
	dialect: string,
	options: Record<string, unknown>,
	sql: string,
	params?: readonly unknown[],
): Promise<T[]>;

export function assertSafeIdentifier(name: string, kind?: string): string;

export const ConnectionFactory: {
	create: (
		provider: string,
		options: Record<string, unknown>,
		opts?: { pooled?: boolean },
	) => Promise<unknown>;
	close: (provider: string, connection: unknown) => Promise<void>;
	executeQuery: <T = Record<string, unknown>>(
		provider: string,
		options: Record<string, unknown>,
		sql: string,
		params?: readonly unknown[],
	) => Promise<T[]>;
	closeAll: () => Promise<void>;
};

export function getRegisteredProvider(dialect: string): {
	testConnection: (options: Record<string, unknown>) => Promise<boolean>;
	getTables?: (
		options: Record<string, unknown>,
		schema: string,
	) => Promise<FoxTableSchema[]>;
};

export function getAdapter(dialect: string): {
	query: <T = Record<string, unknown>>(
		connection: unknown,
		sql: string,
		params: readonly unknown[],
	) => Promise<T[]>;
	beginTransaction: (connection: unknown) => Promise<void>;
	commitTransaction: (connection: unknown) => Promise<void>;
	rollbackTransaction: (connection: unknown) => Promise<void>;
	packageName: string;
};

export const DEFAULT_PORTS: Record<string, number>;

export const PROVIDER_SETTINGS: Record<
	string,
	{
		dialect: string;
		defaultPort: number;
		transactions?: boolean;
		buildConnectionString: (options: Record<string, unknown>) => string;
	}
>;

export function getProviderSettings(dialect: string): {
	dialect: string;
	defaultPort: number;
	transactions?: boolean;
	buildConnectionString: (options: Record<string, unknown>) => string;
};

export function dialectFamily(dialect: string): string;
export function isFileDialect(dialect: string): boolean;

export type SqlPlaceholderStyle = 'dollar' | 'question' | 'colon' | 'at';
export function placeholderStyleFor(dialect: string): SqlPlaceholderStyle;
export function renderPlaceholder(style: SqlPlaceholderStyle, index: number): string;
export function quoteSqlIdentifier(name: string, dialect: string): string;
export function quoteQualifiedName(qualified: string, dialect: string): string;
export function sqlLiteral(value: unknown, dialect: string): string;

export interface SqlToken {
	kind: 'space' | 'comment' | 'word' | 'string' | 'name' | 'dollar' | 'punct';
	start: number;
	end: number;
	upper: string;
	open: string;
	close: string;
}

export type SqlTokenOptions = Record<string, unknown>;
export function sqlReadingsFor(text: string, dialect?: string): SqlTokenOptions[];
export function sqlTokens(
	text: string,
	options?: SqlTokenOptions,
	from?: number,
): Iterable<SqlToken>;
